class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        from functools import lru_cache
        n = len(nums)
        pre = [0] * (n + 1)
        for i, x in enumerate(nums):
            pre[i + 1] = pre[i] + x
        @lru_cache(None)
        def dp(i, j):
            if i == j:
                return True
            for k in range(i, j):
                lok = (k == i) or (pre[k + 1] - pre[i] >= m)
                rok = (k + 1 == j) or (pre[j + 1] - pre[k + 1] >= m)
                if lok and rok and dp(i, k) and dp(k + 1, j):
                    return True
            return False
        return dp(0, n - 1)

