                const lok = k === i || pre[k + 1] - pre[i] >= m;
                const rok = k + 1 === j || pre[j + 1] - pre[k + 1] >= m;
                if (lok && rok && dp[i][k] && dp[k + 1][j]) dp[i][j] = true;
            }
        }
